<script setup>
import {useAccess} from '../composables/access.js';
defineProps({lot:Object,production:Object,deaths:Array,transfers:Array});const emit=defineEmits(['edit']);const {can}=useAccess();
const n=value=>value==null?'Pendiente':Number(value).toLocaleString('es-ES',{maximumFractionDigits:3});
</script>
<template><section class="panel production-panel"><div class="production-heading"><h2>Control del lote {{ lot.code }}</h2><div class="actions"><button class="button" :disabled="!can('accounting_write')" @click="emit('edit',{kind:'death',event:null})">Registrar bajas</button><button class="button" :disabled="!can('accounting_write')" @click="emit('edit',{kind:'transfer',event:null})">Traspasar pienso</button></div></div><div v-if="production" class="production-metrics"><div><small>Peso de entrada</small><strong>{{ n(production.entry_total_kg) }} kg</strong></div><div><small>Salidas vendidas</small><strong>{{ n(production.sold_pigs) }} animales</strong></div><div><small>Bajas registradas</small><strong>{{ n(production.dead_pigs) }} · {{ n(production.mortality_percent) }} %</strong></div><div><small>Índice de conversión</small><strong>{{ n(production.conversion) }} kg/kg</strong><span>{{ production.conversion_final?'Lote conciliado':'Provisional / pendiente de completar' }}</span></div></div><p v-if="production?.remaining_pigs" class="muted">Saldo pendiente de conciliar: {{ production.remaining_pigs }} animales.</p><p v-if="production?.entry_cost_missing" class="muted">Falta el precio de entrada por animal. Puedes completarlo en «Editar lote».</p><h3>Bajas</h3><div v-if="deaths.length" class="table-wrap"><table><thead><tr><th>Fecha</th><th>Animales</th><th>Motivo</th><th></th></tr></thead><tbody><tr v-for="row in deaths" :key="row.id"><td>{{ row.event_date }}</td><td>{{ row.pigs }}</td><td>{{ row.notes }}</td><td><button class="button" :disabled="!can('accounting_write')" @click="emit('edit',{kind:'death',event:row})">Editar</button></td></tr></tbody></table></div><p v-else class="muted">No se han registrado bajas.</p><h3>Traspasos de pienso</h3><div v-if="transfers.length" class="table-wrap"><table><thead><tr><th>Fecha</th><th>Origen → destino</th><th>Kg</th><th>Valor</th><th></th></tr></thead><tbody><tr v-for="row in transfers" :key="row.id"><td>{{ row.event_date }}</td><td>{{ row.source_farm_name }} · {{ row.source_lot_code }} → {{ row.destination_farm_name }} · {{ row.destination_lot_code }}</td><td>{{ n(row.kg) }}</td><td>{{ Number(row.total_amount).toLocaleString('es-ES',{style:'currency',currency:'EUR'}) }}</td><td><button class="button" :disabled="!can('accounting_write')" @click="emit('edit',{kind:'transfer',event:row})">Editar</button></td></tr></tbody></table></div><p v-else class="muted">No hay traspasos de pienso registrados.</p></section></template>
<style scoped>.production-panel{padding:22px;margin:20px 0}.production-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.production-panel h2{font-size:18px}.production-panel h3{font-size:15px;margin:24px 0 12px}.production-panel table{width:100%}.production-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;margin:22px 0}.production-metrics>div{display:grid;gap:8px}.production-metrics small,.production-metrics span{font-size:12px;color:#65748a}@media(max-width:850px){.production-metrics{grid-template-columns:1fr 1fr}}</style>
